preview.css:
:root {
	--w: 400px;
	--h: 46px;
	--reveal: 6px;
	--border-color: #ffffff;
	--border-width: 1px;
	--bg: linear-gradient(135deg, #161225, #231a3d);
	--progress-bg: #571bc3;
	--progress-glow: #571bc3;
	--text: rgba(255, 255, 255, 1);
	--font: "Poppins";
	--textWeight: 500;
	--textSize: 14px;
}

html,
body {
	width: 100%;
	height: 100%;
	margin: 0;
	padding: 0;
	background: transparent;
	overflow: hidden;
}

body {
	display: flex;
	align-items: center;
	justify-content: center;
}

@keyframes goalEnter {
	from { opacity: 0; transform: translateY(10px) scale(.96); }
	to { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes goalBump {
	0% { transform: scale(1) rotate(0deg); }
	35% { transform: scale(1.2) rotate(-10deg); }
	65% { transform: scale(1.05) rotate(6deg); }
	100% { transform: scale(1) rotate(0deg); }
}

@keyframes goalIconGlow {
	0%, 100% { text-shadow: 0 0 0 transparent; }
	35% { text-shadow: 0 0 8px var(--progress-glow), 0 0 16px var(--progress-glow); }
}

@keyframes goalValueExit {
	from { transform: translateY(0); }
	to { transform: translateY(-100%); }
}

@keyframes goalValueEnter {
	from { transform: translateY(-100%); }
	to { transform: translateY(0); }
}

@keyframes goalComplete {
	0% { transform: scale(1); filter: drop-shadow(0 0 0 transparent); }
	25% { transform: scale(1.06); filter: drop-shadow(0 0 16px var(--progress-glow)) drop-shadow(0 0 32px var(--progress-glow)); }
	55% { transform: scale(.98); filter: drop-shadow(0 0 8px var(--progress-glow)); }
	100% { transform: scale(1); filter: drop-shadow(0 0 0 transparent); }
}

@keyframes goalConfetti {
	0% { opacity: 1; transform: translate(0, 0) rotate(0deg); }
	100% { opacity: 0; transform: translate(var(--tx), var(--ty)) rotate(var(--rot)); }
}

.goal-confetti {
	position: absolute;
	top: 30%;
	left: 16%;
	width: 5px;
	height: 5px;
	background: var(--progress-glow);
	opacity: 0;
	pointer-events: none;
	z-index: 6;
	animation: goalConfetti 700ms ease-out forwards;
}

.goal {
	position: relative;
	width: var(--w);
	height: calc(var(--h) + var(--reveal));
	box-sizing: border-box;
	font-family: var(--font), system-ui, -apple-system, Segoe UI, Roboto, Arial;
	line-height: 1;
	animation: goalEnter 520ms cubic-bezier(.2, .9, .2, 1) both;
}

.goal.is-complete {
	animation: goalComplete 900ms cubic-bezier(.2, .9, .2, 1);
}

.goal-info {
	position: absolute;
	left: 0;
	top: 0;
	z-index: 2;
	width: 100%;
	height: var(--h);
	border-radius: calc(var(--h) / 2);
	border: var(--border-width) solid var(--border-color);
	background: var(--bg);
	backdrop-filter: blur(3px);
	box-sizing: border-box;
	overflow: hidden;
	display: flex;
	align-items: center;
	gap: 8px;
	padding: 0 10px 0 5px;
}

.goal-icon {
	width: calc(var(--h) - 10px);
	height: calc(var(--h) - 10px);
	display: flex;
	align-items: center;
	justify-content: center;
	flex: 0 0 auto;
}

.goal-icon.is-bump {
	animation: goalBump 420ms cubic-bezier(.34, 1.56, .64, 1);
}

.goal-icon.is-bump #goalIcon {
	animation: goalIconGlow 420ms ease-out;
}

.goal-value-mask {
	position: relative;
	display: inline-block;
	overflow: hidden;
	line-height: 1;
	vertical-align: bottom;
}

#current {
	display: inline-block;
}

#current.is-entering {
	animation: goalValueEnter 360ms cubic-bezier(.2, .9, .2, 1);
}

.goal-value-ghost {
	position: absolute;
	left: 0;
	top: 0;
	display: inline-block;
	pointer-events: none;
	animation: goalValueExit 360ms cubic-bezier(.4, 0, .8, .2) forwards;
}

#goalIcon {
	color: var(--text);
	font-size: 22px;
	line-height: 1;
	font-variation-settings: "FILL" 1, "wght" 200, "GRAD" 0, "opsz" 24;
	transition: color 400ms ease;
}

.goal.is-complete .goal-info {
	transition: border-color 400ms ease;
	border-color: var(--progress-glow);
}

.goal.is-complete #goalIcon {
	color: var(--progress-glow);
}

.goal-title {
	flex: 1 1 auto;
	min-width: 0;
	overflow: hidden;
	color: var(--text);
	font-weight: var(--textWeight);
	font-size: var(--textSize);
	white-space: nowrap;
	text-overflow: ellipsis;
}

.goal-right {
	flex: 0 0 auto;
	display: flex;
	align-items: center;
	gap: 6px;
	color: var(--text);
	font-weight: var(--textWeight);
	font-size: var(--textSize);
	letter-spacing: .2px;
	white-space: nowrap;
}

.sep {
	opacity: .6;
}

.goal-progress {
	position: absolute;
	left: 0;
	top: calc(var(--h) - 18px);
	z-index: 1;
	width: 0%;
	height: 24px;
	overflow: hidden;
	box-sizing: border-box;
	transition: width 600ms cubic-bezier(.2, .9, .2, 1);
}

.goal-fill {
	position: absolute;
	left: 0;
	top: 0;
	height: 24px;
	background: var(--progress-bg);
	transition: background 400ms ease;
}

.icon {
	display: inline-flex;
	align-items: center;
	justify-content: center;
}

