html,
body {
  margin: 0;
  padding: 0;
  background: transparent;
  overflow: hidden;
}

/* =========================
   Structure générale
   .topbar empile la ligne de texte et la barre, dans l'ordre
   choisi via --order-row / --order-bar (voir applyBorderPosition)
========================= */
.topbar {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  /* Chiffres de largeur fixe (hérité par tous les textes, y compris ceux
     recréés par le carrousel social) : sans ça, la date qui égrène les
     secondes change très légèrement de largeur à chaque tick (polices
     proportionnelles), ce qui recalcule la zone labels (flex:1, centrée)
     et fait "trembler" les labels d'une fraction de pixel à chaque seconde. */
  font-variant-numeric: tabular-nums;
  /* Base du cycle apparition/disparition (voir initAppearance côté JS) :
     transition par défaut pour "fade" (et tout data-anim inconnu) — les
     autres styles déclarent la leur, ce qui l'écrase. */
  opacity: 1;
  transform: none;
  transition: opacity 800ms ease, transform 800ms ease;
}

.text-row {
  order: 1;
  display: flex;
  align-items: center;
  width: 100%;
  flex: 1 1 auto;
  overflow: visible;
}

.zone {
  display: flex;
  align-items: center;
  overflow: visible;
}
.zone.is-hidden {
  display: none;
}

.zone-date {
  order: 0;
  flex: 0 0 auto;
  padding-left: 17px;
}
.zone-labels {
  order: 1;
  flex: 1 1 auto;
  justify-content: center;
}
.zone-social {
  order: 2;
  flex: 0 0 auto;
  padding-right: 20px;
}

