  18% {
    transform: rotate(-10deg) scale(1.08);
    text-shadow:
      0 0 2px rgba(var(--hit-rgb, 255, 255, 255), 1),
      0 0 6px rgba(var(--hit-rgb, 255, 255, 255), 1),
