  36% {
    transform: rotate(10deg) scale(1.08);
    text-shadow:
      0 0 3px rgba(var(--hit-rgb, 255, 255, 255), 1),
      0 0 8px rgba(var(--hit-rgb, 255, 255, 255), 1),
      0 0 16px rgba(var(--hit-rgb, 255, 255, 255), .9);
  }
  54% {
    transform: rotate(-7deg) scale(1.05);
    text-shadow:
      0 0 2px rgba(var(--hit-rgb, 255, 255, 255), 1),
      0 0 6px rgba(var(--hit-rgb, 255, 255, 255), .95),
      0 0 12px rgba(var(--hit-rgb, 255, 255, 255), .75);
  }
  72% {
    transform: rotate(7deg) scale(1.02);
    text-shadow:
      0 0 1px rgba(var(--hit-rgb, 255, 255, 255), .9),
      0 0 4px rgba(var(--hit-rgb, 255, 255, 255), .7),
      0 0 8px rgba(var(--hit-rgb, 255, 255, 255), .5);
  }
  100% {
    transform: rotate(0deg) scale(1);
    text-shadow: 0 0 0px rgba(var(--hit-rgb, 255, 255, 255), 0);
