/* =========================
   Social panel (zer0oes-social-panel)
========================= */
#socials .row {
  display: flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
  overflow: visible;
}
#socials .icon {
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  line-height: 1;
  /* Couleur + ombre viennent de #socials (filter, cf. applyTextTheme) :
     même thème de texte que la date et les labels. */
}
#socials .name {
  line-height: 1;
}
:root {
  --slide: 100px;
}
#socials .icon,
#socials .name {
  will-change: transform, opacity;
}
#socials .icon.anim {
  animation-name: kIconMove, kIconFade;
  animation-timing-function: linear, linear;
  animation-iteration-count: infinite, infinite;
  animation-fill-mode: both, both;
}
#socials .name.anim {
  animation-name: kTextMove, kTextFade;
  animation-timing-function: linear, linear;
  animation-iteration-count: infinite, infinite;
  animation-fill-mode: both, both;
}
@keyframes kIconMove {
  0%, 20% { transform: translateX(var(--slide)); }
  24%     { transform: translateX(0); }
  78%     { transform: translateX(0); }
  82%     { transform: translateX(var(--slide)); }
  100%    { transform: translateX(var(--slide)); }
}
@keyframes kIconFade {
  0%, 18% { opacity: 0; }
  20%     { opacity: 1; }
  80%     { opacity: 1; }
  82%     { opacity: 0; }
  100%    { opacity: 0; }
}
@keyframes kTextMove {
  0%, 22% { transform: translateX(var(--slide)); }
  26%     { transform: translateX(0); }
  72%     { transform: translateX(0); }
  76%     { transform: translateX(var(--slide)); }
  100%    { transform: translateX(var(--slide)); }
}
@keyframes kTextFade {
  0%, 20% { opacity: 0; }
  22%     { opacity: 1; }
  74%     { opacity: 1; }
  76%     { opacity: 0; }
  100%    { opacity: 0; }
}

/* =========================
   Border (zer0oes-bar-border-bottom-2)
========================= */
.line-widget {
  order: 2;
  flex: 0 0 auto;
  width: 100%;
  height: 3px;
  padding: 0 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  box-sizing: border-box;
  filter:
    drop-shadow(0 1px 0 rgba(122, 0, 255, 1))
    drop-shadow(0 2px 0 rgba(120, 190, 255, 0.5));
  /* L'opacité/transform du cycle apparition-disparition vivent sur #topbar
     (voir plus bas) : toute la barre — texte + trait — bouge comme un seul
     bloc, plutôt que le trait seul. */
}
.line {
  flex: 1;
  height: 1px;
  background: #FFFFFF;
}
.dot {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: #FFFFFF;
  flex: 0 0 3px;
}
.topbar:not(.is-hidden) .line-widget {
  animation: lineGlow 2.5s ease-in-out infinite alternate;
}

/* =========================
   Apparition/disparition de TOUTE la barre (date + labels + social + trait)
   — le cycle (voir initAppearance côté JS) pose is-hidden / is-flicker-* /
   is-sweeping sur #topbar, pas seulement sur la barre : les styles
   ci-dessous s'appliquent donc à l'ensemble, qui bouge comme un seul bloc.
========================= */
.topbar[data-anim="fade"].is-hidden,
.topbar[data-anim="sweep"].is-hidden,
.topbar:not([data-anim]).is-hidden {
  opacity: 0;
  transform: scaleX(0.85);
}
.topbar[data-anim="sweep"] {
  transition: opacity 800ms ease, transform 800ms ease;
}

.topbar[data-anim="wipe"] {
  transition: transform 700ms ease;
}
.topbar[data-anim="wipe"].is-hidden {
  opacity: 1;
  transform: scaleX(0);
}

.topbar[data-anim="slide"] {
  transition: opacity 500ms ease, transform 500ms ease;
}
.topbar[data-anim="slide"].is-hidden {
  opacity: 0;
  transform: translateY(6px);
}

.topbar[data-anim="pulse"] {
  transition: opacity 220ms ease-out, transform 220ms ease-out;
}
.topbar[data-anim="pulse"].is-hidden {
  opacity: 0;
  transform: scaleX(0.92);
}

/* Flicker néon : pas de transition CSS, l'opacité est pilotée par les
   keyframes flickerIn/flickerOut (classes temporaires posées par le JS) ;
   l'état final (caché/visible) est figé ici en secours. */
.topbar[data-anim="flicker"] {
  transition: none;
}
.topbar[data-anim="flicker"].is-hidden {
  opacity: 0;
}
.topbar[data-anim="flicker"].is-flicker-out {
  animation: flickerOut var(--border-anim-ms, 400ms) ease-out both;
}
.topbar[data-anim="flicker"].is-flicker-in {
  animation: flickerIn var(--border-anim-ms, 400ms) ease-out both;
}
@keyframes flickerIn {
  0%   { opacity: 0; }
  8%   { opacity: 1; }
  14%  { opacity: 0.15; }
  22%  { opacity: 1; }
  28%  { opacity: 0.25; }
  38%  { opacity: 1; }
  45%  { opacity: 0.4; }
  55%  { opacity: 1; }
  100% { opacity: 1; }
}
@keyframes flickerOut {
  0%   { opacity: 1; }
  10%  { opacity: 0.3; }
  20%  { opacity: 1; }
  30%  { opacity: 0.2; }
  45%  { opacity: 1; }
  55%  { opacity: 0.15; }
  70%  { opacity: 1; }
  85%  { opacity: 0.1; }
  100% { opacity: 0; }
}

/* Balayage lumineux : le fondu ci-dessus (data-anim="sweep") fait
   apparaître/disparaître toute la barre, et en plus un éclat traverse le
   trait pendant l'entrée/la sortie (pseudo-élément ::after sur .line-widget,
   déclenché par .is-sweeping posée sur #topbar). Un halo blanc sur un trait
   déjà blanc serait invisible (pas de contraste) : l'éclat est donc une
   traînée lumineuse colorée qui déborde largement du trait (glow via
   box-shadow multicouche), en resterait sinon un petit point trop discret
   sur 1920px de large. */
.line-widget {
  position: relative;
  overflow: visible;
}
.topbar[data-anim="sweep"] .line-widget::after {
  content: "";
  position: absolute;
  top: 50%;
  left: -8%;
  width: 220px;
  height: 26px;
  margin-left: -110px;
  transform: translateY(-50%);
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    rgba(120, 60, 255, 0) 0%,
    rgba(150, 90, 255, 0.55) 30%,
    rgba(255, 255, 255, 1) 50%,
    rgba(150, 90, 255, 0.55) 70%,
    rgba(120, 60, 255, 0) 100%
  );
  box-shadow:
    0 0 16px 6px rgba(255, 255, 255, 0.9),
    0 0 40px 16px rgba(160, 100, 255, 0.85),
    0 0 70px 26px rgba(120, 60, 255, 0.55);
  opacity: 0;
  pointer-events: none;
}
.topbar[data-anim="sweep"].is-sweeping .line-widget::after {
  animation: sweepMove var(--border-anim-ms, 400ms) ease-out both;
}
@keyframes sweepMove {
  0%   { left: -8%; opacity: 1; }
  100% { left: 108%; opacity: 1; }
}

@keyframes lineGlow {
  from {
    filter:
      drop-shadow(0 1px 0 rgba(122, 0, 255, 0.8))
      drop-shadow(0 2px 0 rgba(120, 190, 255, 0.4));
  }
  to {
    filter:
      drop-shadow(0 1px 0 rgba(122, 0, 255, 1))
      drop-shadow(0 3px 0 rgba(120, 190, 255, 0.7));
  }
}

